3	import {
4	  Users,
5	  Inbox,
6	  Activity,
7	  DollarSign,
8	  Clock,
9	  TrendingUp,
10	  TrendingDown,
11	  Minus,
12	  type LucideIcon,
13	} from "lucide-react";
14	import { Card, CardContent } from "@/components/ui/card";
15	import type { KpiMetric, IconName, TrendDirection } from "@/lib/types";
16	
17	const iconMap: Record<IconName, LucideIcon> = {
18	  users: Users,
19	  inbox: Inbox,
20	  activity: Activity,
21	  "dollar-sign": DollarSign,
22	  clock: Clock,
23	};
24	
25	const trendIconMap: Record<TrendDirection, LucideIcon> = {
26	  up: TrendingUp,
27	  down: TrendingDown,
28	  flat: Minus,
29	};
30	
31	interface KpiCardProps {
32	  metric: KpiMetric;
33	  index: number;
34	}
35	
36	export function KpiCard({ metric, index }: KpiCardProps) {
37	  const Icon = iconMap[metric.iconName];
38	  const TrendIcon = trendIconMap[metric.trend];
39	
40	  // k05 is "Avg SLA" — down trend is good (faster SLA = improvement)
41	  const isInverse = metric.id === "k05";
42	  const isPositive = isInverse
43	    ? metric.trend === "down"
44	    : metric.trend === "up";
45	  const isNegative = isInverse
46	    ? metric.trend === "up"
47	    : metric.trend === "down";
48	
49	  const deltaColorClass = isPositive
50	    ? "text-emerald-600"
51	    : isNegative
52	      ? "text-rose-600"
53	      : "text-muted-foreground";
54	
55	  return (
56	    <Card
57	      className="animate-fade-in-up shadow-card hover:-translate-y-0.5 hover:shadow-soft-md transition-all duration-150"
58	      style={{
59	        animationDelay: `${index * 80}ms`,
60	        animationFillMode: "both",
61	      }}
62	    >
63	      <CardContent className="p-5">
64	        <div className="flex items-center justify-between">
65	          <p className="text-sm font-medium text-muted-foreground">
66	            {metric.label}
67	          </p>
68	          <div className="size-8 rounded-md bg-primary/10 text-primary flex items-center justify-center">
69	            <Icon className="size-4" />
70	          </div>
71	        </div>
72	        <p className="text-2xl font-bold leading-none tabular-nums mt-3">
73	          {metric.value}
74	        </p>
75	        <div className={`flex items-center gap-1 mt-2 ${deltaColorClass}`}>
76	          <TrendIcon className="size-3.5" />
77	          <span className="text-xs font-medium">
78	            {metric.delta > 0 ? "+" : ""}
79	            {metric.delta}%
80	          </span>
81	          <span className="text-xs text-muted-foreground">vs last week</span>
82	        </div>
83	      </CardContent>
84	    </Card>
85	  );
86	}
