1	import {
2	  CheckCircle2,
3	  UserPlus,
4	  Sparkles,
5	  User,
6	  MessageSquare,
7	  Plus,
8	  type LucideIcon,
9	} from "lucide-react";
10	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
11	import { activity } from "@/lib/mock/activity";
12	import type { ActivityType } from "@/lib/types";
13	
14	const ANCHOR = "2026-04-10T12:00:00Z";
15	
16	type ActivityIconConfig = {
17	  icon: LucideIcon;
18	  className: string;
19	};
20	
21	const activityIconMap: Record<ActivityType, ActivityIconConfig> = {
22	  request_delivered: { icon: CheckCircle2, className: "text-emerald-600" },
23	  client_added: { icon: UserPlus, className: "text-blue-500" },
24	  brief_generated: { icon: Sparkles, className: "text-primary" },
25	  request_assigned: { icon: User, className: "text-muted-foreground" },
26	  comment_added: { icon: MessageSquare, className: "text-muted-foreground" },
27	  request_created: { icon: Plus, className: "text-muted-foreground" },
28	};
29	
30	function getInitials(name: string): string {
31	  return name
32	    .split(" ")
33	    .map((part) => part[0] ?? "")
34	    .slice(0, 2)
35	    .join("")
36	    .toUpperCase();
37	}
38	
39	function formatRelativeTime(timestamp: string): string {
40	  const eventMs = new Date(timestamp).getTime();
41	  const nowMs = new Date(ANCHOR).getTime();
42	  const diffMs = nowMs - eventMs;
43	  const diffMinutes = Math.round(diffMs / (1000 * 60));
44	  const diffHours = Math.round(diffMs / (1000 * 60 * 60));
45	  const diffDays = Math.round(diffMs / (1000 * 60 * 60 * 24));
46	
47	  if (diffMinutes < 60) return `${diffMinutes}m ago`;
48	  if (diffHours < 24) return `${diffHours}h ago`;
49	  return `${diffDays}d ago`;
50	}
51	
52	const recentEvents = activity.slice(0, 10);
53	
54	export function ActivityFeed() {
55	  return (
56	    <Card className="shadow-card">
57	      <CardHeader className="pb-3">
58	        <CardTitle className="text-base font-semibold">
59	          Recent activity
60	        </CardTitle>
61	      </CardHeader>
62	      <CardContent>
63	        <ul className="space-y-4">
64	          {recentEvents.map((event) => {
65	            const iconConfig = activityIconMap[event.type];
66	            const TypeIcon = iconConfig.icon;
67	
68	            return (
69	              <li key={event.id} className="flex items-start gap-3">
70	                {/* Avatar with initials */}
71	                <div className="size-8 rounded-full bg-primary/10 text-primary text-xs font-semibold flex items-center justify-center shrink-0">
72	                  {getInitials(event.actorName)}
73	                </div>
74	
75	                {/* Content */}
76	                <div className="flex-1 min-w-0 space-y-0.5">
77	                  <p className="text-sm leading-snug">
78	                    <strong className="font-medium">{event.actorName}</strong>{" "}
79	                    {event.action}{" "}
80	                    <strong className="font-medium">{event.target}</strong>
81	                  </p>
82	                  <p className="text-xs text-muted-foreground">
83	                    {formatRelativeTime(event.timestamp)}
84	                  </p>
85	                </div>
86	
87	                {/* Type icon */}
88	                <TypeIcon className={`size-4 shrink-0 mt-0.5 ${iconConfig.className}`} />
89	              </li>
90	            );
91	          })}
92	        </ul>
93	      </CardContent>
94	    </Card>
95	  );
96	}
